def flowFile = session.get()
if (!flowFile) return

def destDb = flowFile.getAttribute('dest_database')
def destSchema = flowFile.getAttribute('dest_schema')
def tableUpper = flowFile.getAttribute('table_upper')
def stagingTable = flowFile.getAttribute('staging_table')
def srcCols = flowFile.getAttribute('src_cols')
def pkCols = flowFile.getAttribute('pk_cols')
def colDefs = flowFile.getAttribute('col_defs')
def replicationType = flowFile.getAttribute('replication_type') ?: 'incremental'
def timestampCol = flowFile.getAttribute('timestamp_col') ?: ''
def srcSchema = flowFile.getAttribute('src_schema')
def tableName = flowFile.getAttribute('table_name')

if (!tableUpper || !srcCols) {
    log.error("Missing required attributes: table_upper=" + tableUpper + ", src_cols=" + srcCols)
    session.transfer(flowFile, REL_FAILURE)
    return
}

def fqMain = destDb + "." + destSchema + "." + tableUpper
def fqStaging = destDb + "." + destSchema + "." + stagingTable

def allCols = srcCols.split(',').collect { it.trim().toUpperCase() }
def allColsWithLoaded = allCols + ['_LOADED_AT']

// Generate CREATE TABLE IF NOT EXISTS DDL
def ddlCols = colDefs ? colDefs + ", _LOADED_AT TIMESTAMP_NTZ" : allColsWithLoaded.collect { it + " VARCHAR" }.join(', ')
def createMainSql = "CREATE TABLE IF NOT EXISTS " + fqMain + " (" + ddlCols + ")"
def createStagingSql = "CREATE TABLE IF NOT EXISTS " + fqStaging + " (" + ddlCols + ")"

// Base extract SQL
def extractSql = "SELECT " + srcCols + " FROM " + srcSchema + "." + tableName

def mergeSql
def truncateSql
def preLoadSql
def insertCols = allColsWithLoaded.join(', ')

if (replicationType == 'snapshot') {
    // INSERT OVERWRITE atomically replaces all rows in the main table.
    // No gap where the table is empty - readers always see either old or new data.
    preLoadSql = ""
    mergeSql = "INSERT OVERWRITE INTO " + fqMain + " (" + insertCols + ") SELECT " + insertCols + " FROM " + fqStaging
    truncateSql = "TRUNCATE TABLE " + fqStaging
} else {
    if (!pkCols) {
        log.error("Incremental mode requires pk_cols for table " + tableName)
        session.transfer(flowFile, REL_FAILURE)
        return
    }
    if (!timestampCol) {
        log.error("Incremental mode requires a timestamp column for table " + tableName)
        session.transfer(flowFile, REL_FAILURE)
        return
    }
    def pkList = pkCols.split(',').collect { it.trim().toUpperCase() }
    def nonPkCols = allCols.findAll { !(it in pkList) }
    def nonPkColsWithLoaded = nonPkCols + ['_LOADED_AT']

    def partitionBy = pkList.join(', ')
    def onClause = pkList.collect { "T." + it + " = S." + it }.join(' AND ')
    def updateSet = nonPkColsWithLoaded.collect { "T." + it + " = S." + it }.join(', ')
    def insertVals = allColsWithLoaded.collect { "S." + it }.join(', ')

    preLoadSql = ""
    mergeSql = "MERGE INTO " + fqMain + " T USING (SELECT * FROM " + fqStaging + " QUALIFY ROW_NUMBER() OVER (PARTITION BY " + partitionBy + " ORDER BY _LOADED_AT DESC) = 1) S ON " + onClause + " WHEN MATCHED THEN UPDATE SET " + updateSet + " WHEN NOT MATCHED THEN INSERT (" + insertCols + ") VALUES (" + insertVals + ")"
    truncateSql = "TRUNCATE TABLE " + fqStaging
}

flowFile = session.putAttribute(flowFile, 'extract_sql', extractSql)
flowFile = session.putAttribute(flowFile, 'merge_sql', mergeSql)
flowFile = session.putAttribute(flowFile, 'truncate_sql', truncateSql)
flowFile = session.putAttribute(flowFile, 'pre_load_sql', preLoadSql)
flowFile = session.putAttribute(flowFile, 'create_main_sql', createMainSql)
flowFile = session.putAttribute(flowFile, 'create_staging_sql', createStagingSql)

session.transfer(flowFile, REL_SUCCESS)
